export function verse(n: number): string {
  if (n < 1 || n > animals.length) {
    throw new Error("Invalid verse number");
  }

  let result = `I know an old lady who swallowed a ${animals[n - 1]}.\n`;
  result += actions[n - 1] + "\n";

  for (let i = n - 1; i > 0; i--) {
    result += `She swallowed the ${animals[i]} to catch the ${animals[i - 1]}`;
    if (i > 1) {
      result += ` that ${actions[i - 1]}`;
    }
    result += ".\n";
  }

  result += "I don't know why she swallowed the fly. Perhaps she'll die.\n";
  return result;
}

export function verses(start: number, end: number): string {
  if (start < 1 || end > animals.length || start > end) {
    throw new Error("Invalid verse range");
  }

  let result = "";
  for (let i = start; i <= end; i++) {
    result += verse(i);
    if (i < end) {
      result += "\n";
    }
  }
  return result;
}

