export interface Nested extends Array<number | null | undefined | Nested> {}

export function flatten(input: Nested): number[] {
  const result: number[] = [];

  function flattenHelper(arr: Nested) {
    for (const item of arr) {
      if (Array.isArray(item)) {
        flattenHelper(item);
      } else if (item !== null && item !== undefined) {
        result.push(item);
      }
    }
  }

  flattenHelper(input);
  return result;
}

