// @openarc:end wordy.answer

export function answer(question: string): number {
  const questionRegex = /^What is\s+(.*?)(\?|\.|!)$/;
  const match = question.match(questionRegex);

  if (!match) {
    throw new Error("Invalid question format");
  }

  const expression = match[1].replace(/\s+/g, ' ').trim();
  const tokens = expression.split(' ');

  if (tokens.length % 2 !== 1) {
    throw new Error("Invalid syntax");
  }

  let result = parseInt(tokens[0], 10);

  for (let i = 1; i < tokens.length; i += 2) {
    const operator = tokens[i];
    const nextValue = parseInt(tokens[i + 1], 10);

    switch (operator) {
      case 'plus':
        result += nextValue;
        break;
      case 'minus':
        result -= nextValue;
        break;
      case 'multiplied by':
        result *= nextValue;
        break;
      case 'divided by':
        if (nextValue === 0) {
          throw new Error("Division by zero");
        }
        result /= nextValue;
        break;
      default:
        throw new Error("Unsupported operation");
    }
  }

  return result;
}

