const animals = [
  "fly",
  "spider",
  "bird",
  "cat",
  "dog",
  "goat",
  "cow",
  "horse"
];

const actions = [
  "",
  "It wriggled and jiggled and tickled inside her.",
  "How absurd to swallow a bird!",
  "Imagine that, to swallow a cat!",
  "What a hog, to swallow a dog!",
  "Just opened her throat and swallowed a goat!",
  "I don't know how she swallowed a cow!",
  "She's dead, of course!"
];

export function verse(n: number): string {
  if (n < 1 || n > animals.length) {
    throw new Error("Invalid verse number");
  }

  let result = `I know an old lady who swallowed a ${animals[n - 1]}.\n`;
  result += actions[n - 1] + "\n";

  for (let i = n - 1; i > 0; i--) {
    result += `She swallowed the ${animals[i]} to catch the ${animals[i - 1]}`;
    if (i > 1) {
      result += ` that ${actions[i - 1]}`;
    }
    result += ".\n";
  }

  result += "I don't know why she swallowed the fly. Perhaps she'll die.\n";
  return result;
}

export function verses(start: number, end: number): string {
  if (start < 1 || end > animals.length || start > end) {
    throw new Error("Invalid verse range");
  }

  let result = "";
  for (let i = start; i <= end; i++) {
    result += verse(i);
    if (i < end) {
      result += "\n";
    }
  }
  return result;
}

function verse(n: number): string {
  const animals = [
    { name: "fly", rhyme: "I don't know why she swallowed the fly. Perhaps she'll die." },
    { name: "spider", rhyme: "It wriggled and jiggled and tickled inside her." },
    { name: "bird", rhyme: "How absurd to swallow a bird!" },
    { name: "cat", rhyme: "Imagine that, to swallow a cat!" },
    { name: "dog", rhyme: "What a hog, to swallow a dog!" },
    { name: "goat", rhyme: "Just opened her throat and swallowed a goat!" },
    { name: "cow", rhyme: "I don't know how she swallowed a cow!" },
    { name: "horse", rhyme: "She's dead, of course!" }
  ];

  let result = `I know an old lady who swallowed a ${animals[n - 1].name}.\n`;
  if (n > 1) {
    result += animals[n - 1].rhyme + "\n";
    for (let i = n - 2; i >= 0; i--) {
      result += `She swallowed the ${animals[i].name} to catch the ${animals[i + 1].name}.\n`;
    }
  }
  result += animals[0].rhyme;
  return result;
}

function verses(start: number, end: number): string {
  let result = "";
  for (let i = start; i <= end; i++) {
    result += verse(i);
    if (i < end) {
      result += "\n";
    }
  }
  return result;
}

